  var closer = document.getElementById("score-close");
  var panel = document.getElementById("score-panel");
  var tabs = panel.querySelectorAll("[role='tab']");
  var leagues = panel.querySelectorAll(".leagues [role='radio']");
  var winners = panel.querySelectorAll(".score-who");

  function sideBySide() {
    return window.matchMedia("(min-width: 641px)").matches;
  }
  function fitSplit() {
    var split = !!(main && main.classList.contains("score-open") && sideBySide());
    document.documentElement.classList.toggle("score-split", split);
  }
  function placeDrawer() {
    if (main) return;
    var header = document.querySelector("header");
    var bottom = header ? Math.max(0, header.getBoundingClientRect().bottom) : 0;
    panel.style.top = Math.round(bottom + 8) + "px";
    panel.style.maxHeight = "calc(100vh - " + Math.round(bottom + 16) + "px)";
  }
  function showScoreboard() {
    var top = window.scrollY;
    if (main) main.classList.add("score-open");
    else document.documentElement.classList.add("score-drawer");
    panel.hidden = false;
    opener.setAttribute("aria-expanded", "true");
    fitSplit();
    placeDrawer();
    var wrap = main && main.querySelector(".nr-wrap");
    if (wrap && document.documentElement.classList.contains("score-split")) wrap.scrollTop = top;
    else if (main) panel.scrollIntoView({ block: "nearest" });
    closer.focus();
  }
  function hideScoreboard() {
    var wrap = main && main.querySelector(".nr-wrap");
    var top = wrap ? wrap.scrollTop : 0;
    document.documentElement.classList.remove("score-split");
    document.documentElement.classList.remove("score-drawer");
    if (main) main.classList.remove("score-open");
    panel.hidden = true;
    opener.setAttribute("aria-expanded", "false");
    if (top) window.scrollTo(0, top);
    opener.focus();
  }
  window.addEventListener("resize", function () {
    fitSplit();
    if (!panel.hidden) placeDrawer();
  });
  opener.addEventListener("click", function () {
    if (panel.hidden) showScoreboard();
    else hideScoreboard();
  });
  closer.addEventListener("click", hideScoreboard);
  document.addEventListener("keydown", function (event) {
    if (event.key === "Escape" && !panel.hidden) hideScoreboard();
  });


  tabs.forEach(function (tab) {
    tab.addEventListener("click", function () {
      tabs.forEach(function (other) {
        var on = other === tab;
        other.setAttribute("aria-selected", on ? "true" : "false");
        other.tabIndex = on ? 0 : -1;
        var sheet = document.getElementById(other.getAttribute("aria-controls"));
        if (sheet) sheet.hidden = !on;
      });
    });
  });
  leagues.forEach(function (league) {
    league.addEventListener("click", function () {
      leagues.forEach(function (other) {
        var on = other === league;
        other.setAttribute("aria-checked", on ? "true" : "false");
        var sheet = document.getElementById(other.getAttribute("aria-controls"));
        if (sheet) sheet.hidden = !on;
      });
    });
  });
  winners.forEach(function (button) {
    button.addEventListener("click", function () {
      var open = button.getAttribute("aria-expanded") === "true";
      winners.forEach(function (other) {
        other.setAttribute("aria-expanded", "false");
        var otherCard = document.getElementById(other.getAttribute("aria-controls"));
        if (otherCard) otherCard.hidden = true;
      });
      if (!open) {
        button.setAttribute("aria-expanded", "true");
        var card = document.getElementById(button.getAttribute("aria-controls"));
        if (card) card.hidden = false;
      }
    });
  });

